#!/usr/bin/env python3
"""Group a run's attempts (or the difference of two runs) into causes a developer can act on.

usage: prof-buckets.py RUN [RUN_B]   (RUN = tools/profile.sh's OUT or its profile.json)

Buckets are named by what the instruction is for, from the function's name and layer:
  program: compiled code      the benchmark's own functions
  program: libc mem*          memcpy/memmove/memset/memcmp/strlen... (the C library's copies)
  program: malloc             malloc/free/realloc/calloc and the heap's own functions
  program: SDK runtime        __capstone_* / capstone_* / delegate_* / dl_* in the image
  program: libc other         everything else in the image that is not the benchmark (printf,
                              stdio, qsort...) -- recognized by a libc name list, imperfectly
  launcher / job-helper / module / firmware / profrun
  kernel: pin + fault         get_user_pages, follow_page*, handle_mm_fault, the module's pins
  kernel: page alloc/free     buddy allocator, free lists, lru, folio bookkeeping
  kernel: memcg/stat          cgroup and node/lruvec statistics
  kernel: shmem               tmpfs/shmem pages (the image copy, the domain's memory)
  kernel: copy user           copy_to/from_user, memcpy/memset in the kernel
  kernel: proc/printk         seq_file and printk formatting and ring-buffer reads
  kernel: locks               spinlocks, mutexes, rcu
  kernel: syscall/sched       entry/exit, scheduler, signals, wait
  kernel: net/ssh             TCP/IP and virtio-net (the SSH session that carries the command)
  kernel: fs/9p/virtio        the share and the block device
  kernel: idle                the idle loop (varies run to run, nobody's work)
  kernel: other
  other                       unattributed addresses (the shell, bytes that match no image)
The buckets sum to the total, so a delta table accounts for every attempt.
"""
import json, os, re, sys

