PROGRAM = [("program: libc mem*", LIBC_MEM), ("program: malloc", MALLOC), ("program: SDK runtime", SDK), ("program: libc other", LIBC_OTHER)]


def bucket(cls, fn):
    if cls == "program":
        for name, rx in PROGRAM:
            if rx.match(fn):
                return name
        return "program: compiled code"
    if cls == "kernel":
        for name, rx in KERNEL:
            if rx.search(fn):
                return name
        return "kernel: other"
    if cls == "kernel idle":
        return "kernel: idle"
    return cls


def load(p):
    if os.path.isdir(p):
        p = os.path.join(p, "profile.json")
    d = json.load(open(p))
    out = {}
    for c, f, v in d["all_functions"]:
        out[bucket(c, f)] = out.get(bucket(c, f), 0) + v
    return d["total_attempts"], out


ta, ba = load(sys.argv[1])
if len(sys.argv) > 2:
    tb, bb = load(sys.argv[2])
    keys = sorted(set(ba) | set(bb), key=lambda k: -abs(bb.get(k, 0) - ba.get(k, 0)))
    print(f"{'bucket':26s} {'A':>16s} {'B':>16s} {'B-A':>16s} {'share of delta':>14s}")
    delta = tb - ta
    for k in keys:
        d = bb.get(k, 0) - ba.get(k, 0)
        print(f"{k:26s} {ba.get(k, 0):16,} {bb.get(k, 0):16,} {d:+16,} {100 * d / delta if delta else 0:13.1f}%")
    print(f"{'total':26s} {ta:16,} {tb:16,} {delta:+16,}")
else:
    for k, v in sorted(ba.items(), key=lambda kv: -kv[1]):
        print(f"{k:26s} {v:16,} {100 * v / ta:6.2f}%")
    print(f"{'total':26s} {ta:16,}")
